INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ALEVI','Alevi-Bektashi (Anatolian)',1300,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BIRGE_BEKTASHI','secondary scholarship','John Kingsley Birge, The Bektashi Order of Dervishes (Luzac/Hartford, 1937)','Foundational study of Bektashi doctrine, cosmology, the Allah-Muhammad-Ali triad, Kirklar/cem tradition, and Haji Bektash Veli'),
 ('SRC_DRESSLER_WRITING','secondary scholarship','Markus Dressler, Writing Religion: The Making of Turkish Alevi Islam (Oxford UP, 2013)','Genealogy of modern Alevi identity, the Alevi understanding of the Ali-centric triad, and the Kizilbash-Alevi tradition''s formation'),
 ('SRC_SHANKLAND_ALEVIS','secondary scholarship','David Shankland, The Alevis in Turkey: The Emergence of a Secular Islamic Tradition (RoutledgeCurzon, 2003)','Ethnography of Alevi cem ceremony, dede/ocak system, Muharrem/matem observance, and Anatolian Alevi belief and practice'),
 ('SRC_KARAMUSTAFA_GODS','secondary scholarship','Ahmet T. Karamustafa, God''s Unruly Friends: Dervish Groups in the Islamic Later Middle Period 1200-1550 (Univ. of Utah Press, 1994)','Antinomian Anatolian dervish milieu (Abdalan-i Rum, Qalandars) underlying Bektashi formation')
INSERT INTO _e VALUES
 ('ENT_ALV_KIRKLAR','Kirklar Meclisi (Assembly of the Forty)','Saint collective','Saint collective','Alevi','mystical assembly / archetype of the cem','B','The Forty Saints (Kirklar) whose primordial assembly, presided over by Ali, is the mythic archetype of the cem ceremony; central Alevi-Bektashi collective. Attested in Birge and Alevi buyruk lore. Cohort hub.'),
 ('ENT_ALV_TRINITY','Allah-Muhammad-Ali (the Alevi triad)','Theological category','Theological category','Alevi','divine unity expressed as a triadic formula','B','The Alevi-Bektashi understanding of divine unity expressed in the formula Hak-Muhammad-Ali, in which Ali is venerated as the locus of divine manifestation; doctrinally distinct from Sunni Islam. Attested in Birge and Dressler.'),
 ('ENT_ALV_HAJI_BEKTASH','Haji Bektash Veli (Alevi-Bektashi veneration)','Saint','Saint','Alevi','eponymous saint / pir of the path','B','The 13th-c. Anatolian saint venerated as pir and patron of the Alevi-Bektashi path; the Alevi reception of the historical figure recorded at ENT_SUF_BEKTASH. Velayetname hagiography; Birge.'),
 ('ENT_ALV_PIR_SULTAN','Pir Sultan Abdal','Mystic/saint','Mystic/saint','Alevi','saint-poet / martyr of the tradition','B','16th-c. Alevi saint-poet (asik) executed by Ottoman authorities; his nefes hymns are central to Alevi devotional repertoire and identity. Attested poet of the Kizilbash-Alevi milieu.'),
 ('ENT_ALV_CEM','Cem (the gathering)','Ritual category','Ritual category','Alevi','core communal worship ceremony','B','The central Alevi-Bektashi communal worship gathering led by a dede, modeled on the primordial Kirklar assembly; includes the semah. Publicly attested ritual category (interiors not modeled). Shankland; Birge.'),
 ('ENT_ALV_SEMAH','Semah','Ritual category','Ritual category','Alevi','turning ritual dance within the cem','B','The ritual turning movement performed during the cem, understood as imitating the turning of the Forty and the cosmos. UNESCO-recognized; publicly attested. Birge.'),
 ('ENT_ALV_DEDE','Dede (spiritual guide)','Spiritual office','Spiritual office','Alevi','hereditary religious office leading the community','B','The hereditary spiritual leader of an Alevi community, drawn from sacred lineages (ocak) tracing descent to the Ahl al-Bayt; presides over the cem. Attested institution; Shankland, Dressler.'),
 ('ENT_ALV_OCAK','Ocak (sacred lineage)','Spiritual/social category','Spiritual/social category','Alevi','hereditary holy lineage system','B','The system of sacred hearths/lineages from which dedes descend, claiming genealogical connection to the Imams and saints; organizes Alevi sacred authority. Attested; Dressler.'),
 ('ENT_ALV_HIZIR','Hizir (Alevi veneration)','Holy figure','Holy figure','Alevi','immortal helper, patron of the distressed','B','The Alevi veneration of Hizir (Khidr) as the ever-living helper invoked in distress, honored with the Hizir fast; the Alevi reception of the figure at ENT_ISL_KHIDR. Attested in Alevi practice.'),
 ('ENT_ALV_TWELVE_IMAMS','The Twelve Imams (Alevi veneration / On Iki Imam)','Holy collective','Holy collective','Alevi','venerated Imams central to Alevi devotion','B','The Twelve Imams as venerated in Alevi-Bektashi devotion (On Iki Imam), commemorated in the Muharrem mourning and matem fast; the Alevi reception of the Shi''a Imamate (cf. ENT_ISL_INFALLIBLES / ENT_ISL_AHL_BAYT). Attested.'),
 ('ENT_ALV_MUHARREM','Muharrem / Matem (Alevi mourning)','Ritual/devotional category','Ritual/devotional category','Alevi','mourning observance for Husayn and the Imams','C','The Alevi twelve-day Muharrem mourning fast (matem) commemorating Husayn''s martyrdom at Karbala and the Twelve Imams, ended by Ashura. Publicly attested observance; Shankland.'),
 ('ENT_ALV_BUYRUK','Buyruk (the Book of Command)','Sacred text/principle','Sacred text/principle','Alevi','doctrinal/catechetical text corpus','C','The Buyruk, the body of Alevi-Bektashi doctrinal texts transmitting belief, the cem, and the path; ascribed in tradition to Ja''far al-Sadiq / Shaykh Safi lineages. Attested manuscript tradition.'),
 ('ENT_ALV_KIZILBASH','Kizilbash (Qizilbash, Alevi forebears)','Movement','Movement','Alevi','historical Safavid-allied Anatolian devotees','B','The Kizilbash, the Safavid-allied heterodox Anatolian Turkmen devotees of Ali and the Safavid shaykhs, the historical antecedent of modern Alevis. Attested; Dressler, Karamustafa.'),
 ('ENT_ALV_ABDALAN_RUM','Abdalan-i Rum (Abdals of Anatolia)','Initiate order','Initiate order','Alevi','antinomian Anatolian dervish milieu','C','The wandering antinomian dervish groups of medieval Anatolia among whom the Bektashi tradition crystallized; matrix of Alevi-Bektashi formation. Attested; Karamustafa, God''s Unruly Friends.'),
 ('ENT_ALV_KAYGUSUZ','Kaygusuz Abdal','Sufi poet','Sufi poet','Alevi','early Bektashi saint-poet','C','Late-14th/15th-c. dervish poet, a foundational Bektashi literary saint whose verse shaped the tradition''s hymnody. Attested Bektashi poet; Birge, Karamustafa.'),
 ('ENT_ALV_BALIM_SULTAN','Balim Sultan','Founder/saint','Founder/saint','Alevi','organizer (pir-i sani) of the Bektashi order','C','Early-16th-c. saint called the ''second pir'' (pir-i sani) credited with systematizing Bektashi ritual and organization at the Pir Evi (Haji Bektash lodge). Attested; Birge.');
