INSERT INTO _p VALUES
 ('ENT_ALV_KIRKLAR','PER_ALEVI','The Forty Saints (Kirklar) whose primordial assembly, presided over by Ali, is the mythic archetype of the cem ceremony; central Alevi-Bektashi collective. Attested in Birge and Alevi buyruk lore. Cohort hub.'),
 ('ENT_ALV_TRINITY','PER_ALEVI','The Alevi-Bektashi understanding of divine unity expressed in the formula Hak-Muhammad-Ali, in which Ali is venerated as the locus of divine manifestation; doctrinally distinct from Sunni Islam. Attested in Birge and Dressler.'),
 ('ENT_ALV_HAJI_BEKTASH','PER_ALEVI','The 13th-c. Anatolian saint venerated as pir and patron of the Alevi-Bektashi path; the Alevi reception of the historical figure recorded at ENT_SUF_BEKTASH. Velayetname hagiography; Birge.'),
 ('ENT_ALV_PIR_SULTAN','PER_ALEVI','16th-c. Alevi saint-poet (asik) executed by Ottoman authorities; his nefes hymns are central to Alevi devotional repertoire and identity. Attested poet of the Kizilbash-Alevi milieu.'),
 ('ENT_ALV_CEM','PER_ALEVI','The central Alevi-Bektashi communal worship gathering led by a dede, modeled on the primordial Kirklar assembly; includes the semah. Publicly attested ritual category (interiors not modeled). Shankland; Birge.'),
 ('ENT_ALV_SEMAH','PER_ALEVI','The ritual turning movement performed during the cem, understood as imitating the turning of the Forty and the cosmos. UNESCO-recognized; publicly attested. Birge.'),
 ('ENT_ALV_DEDE','PER_ALEVI','The hereditary spiritual leader of an Alevi community, drawn from sacred lineages (ocak) tracing descent to the Ahl al-Bayt; presides over the cem. Attested institution; Shankland, Dressler.'),
 ('ENT_ALV_OCAK','PER_ALEVI','The system of sacred hearths/lineages from which dedes descend, claiming genealogical connection to the Imams and saints; organizes Alevi sacred authority. Attested; Dressler.'),
 ('ENT_ALV_HIZIR','PER_ALEVI','The Alevi veneration of Hizir (Khidr) as the ever-living helper invoked in distress, honored with the Hizir fast; the Alevi reception of the figure at ENT_ISL_KHIDR. Attested in Alevi practice.'),
 ('ENT_ALV_TWELVE_IMAMS','PER_ALEVI','The Twelve Imams as venerated in Alevi-Bektashi devotion (On Iki Imam), commemorated in the Muharrem mourning and matem fast; the Alevi reception of the Shi''a Imamate (cf. ENT_ISL_INFALLIBLES / ENT_ISL_AHL_BAYT). Attested.'),
 ('ENT_ALV_MUHARREM','PER_ALEVI','The Alevi twelve-day Muharrem mourning fast (matem) commemorating Husayn''s martyrdom at Karbala and the Twelve Imams, ended by Ashura. Publicly attested observance; Shankland.'),
 ('ENT_ALV_BUYRUK','PER_ALEVI','The Buyruk, the body of Alevi-Bektashi doctrinal texts transmitting belief, the cem, and the path; ascribed in tradition to Ja''far al-Sadiq / Shaykh Safi lineages. Attested manuscript tradition.'),
 ('ENT_ALV_KIZILBASH','PER_ALEVI','The Kizilbash, the Safavid-allied heterodox Anatolian Turkmen devotees of Ali and the Safavid shaykhs, the historical antecedent of modern Alevis. Attested; Dressler, Karamustafa.'),
 ('ENT_ALV_ABDALAN_RUM','PER_ALEVI','The wandering antinomian dervish groups of medieval Anatolia among whom the Bektashi tradition crystallized; matrix of Alevi-Bektashi formation. Attested; Karamustafa, God''s Unruly Friends.'),
 ('ENT_ALV_KAYGUSUZ','PER_ALEVI','Late-14th/15th-c. dervish poet, a foundational Bektashi literary saint whose verse shaped the tradition''s hymnody. Attested Bektashi poet; Birge, Karamustafa.'),
 ('ENT_ALV_BALIM_SULTAN','PER_ALEVI','Early-16th-c. saint called the ''second pir'' (pir-i sani) credited with systematizing Bektashi ritual and organization at the Pir Evi (Haji Bektash lodge). Attested; Birge.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ALV_TRINITY','member_of','ENT_ALV_KIRKLAR','medium','The Hak-Muhammad-Ali triad is the divine center invoked at the Kirklar assembly / cem; grouped under the cohort hub as core Alevi cosmology.'),
 ('ENT_ALV_HAJI_BEKTASH','member_of','ENT_ALV_KIRKLAR','medium','Haji Bektash is the eponymous pir of the tradition centered on the Kirklar/cem archetype; wired to the cohort hub.'),
 ('ENT_ALV_PIR_SULTAN','member_of','ENT_ALV_KIRKLAR','medium','Pir Sultan Abdal is a saint of the same Alevi tradition whose hymns are sung in the cem rooted in the Kirklar archetype.'),
 ('ENT_ALV_CEM','member_of','ENT_ALV_KIRKLAR','medium','The cem is the living enactment of the Kirklar assembly; grouped under the hub.'),
 ('ENT_ALV_HIZIR','member_of','ENT_ALV_KIRKLAR','low','Hizir is a venerated holy figure of the Alevi tradition organized around the Kirklar/cem; wired to the hub.'),
 ('ENT_ALV_TWELVE_IMAMS','member_of','ENT_ALV_KIRKLAR','medium','The Twelve Imams are venerated throughout Alevi devotion centered on the cem/Kirklar; grouped under the hub.'),
 ('ENT_ALV_KIZILBASH','member_of','ENT_ALV_KIRKLAR','low','The Kizilbash are the historical Alevi community whose tradition centers on the Kirklar/cem archetype; wired to the hub.'),
 ('ENT_ALV_ABDALAN_RUM','member_of','ENT_ALV_KIRKLAR','low','The Abdalan-i Rum are the dervish milieu of the Alevi-Bektashi tradition organized around the cem/Kirklar; grouped under the hub.'),
 ('ENT_ALV_SEMAH','associated_ritual','ENT_ALV_CEM','high','The semah turning dance is performed within the cem ceremony.'),
 ('ENT_ALV_DEDE','presides_over','ENT_ALV_CEM','high','The dede leads and presides over the cem gathering.'),
 ('ENT_ALV_DEDE','member_of','ENT_ALV_OCAK','high','Dedes derive their authority from descent within a sacred ocak lineage.'),
 ('ENT_ALV_CEM','reception_of','ENT_ALV_KIRKLAR','high','The cem is explicitly understood as the re-enactment of the primordial assembly of the Forty.'),
 ('ENT_ALV_MUHARREM','associated_ritual','ENT_ALV_TWELVE_IMAMS','high','The Muharrem/matem mourning fast commemorates Husayn and the Twelve Imams.'),
 ('ENT_ALV_BUYRUK','member_of','ENT_ALV_KIRKLAR','low','The Buyruk is the doctrinal corpus of the Alevi tradition centered on the cem/Kirklar; grouped under the hub.'),
 ('ENT_ALV_BALIM_SULTAN','member_of','ENT_ALV_KIRKLAR','low','Balim Sultan, the pir-i sani, organized Bektashi ritual life around the cem/Kirklar archetype; wired to the hub.'),
 ('ENT_ALV_KAYGUSUZ','member_of','ENT_ALV_KIRKLAR','low','Kaygusuz Abdal is a foundational Bektashi saint-poet of the tradition centered on the cem/Kirklar.'),
 ('ENT_ALV_KIRKLAR','presided_over_by','ENT_ISL_ALI','medium','In Alevi-Bektashi lore the assembly of the Forty is presided over by Ali (existing ENT_ISL_ALI), the central holy figure of the tradition.'),
 ('ENT_ALV_TRINITY','reception_of','ENT_ISL_ALI','high','The Alevi Hak-Muhammad-Ali triad receives Ali ibn Abi Talib (existing) as the locus of divine manifestation.'),
 ('ENT_ALV_TRINITY','reception_of','ENT_ISL_MUHAMMAD','high','The Alevi triad incorporates the Prophet Muhammad (existing ENT_ISL_MUHAMMAD).'),
 ('ENT_ALV_TRINITY','reception_of','ENT_ISL_ALLAH','high','The triad''s Hak (the Truth/God) is the Alevi reception of Allah (existing ENT_ISL_ALLAH).'),
 ('ENT_ALV_HAJI_BEKTASH','reception_of','ENT_SUF_BEKTASH','high','ENT_ALV_HAJI_BEKTASH is the Alevi-Bektashi veneration of the historical Hajji Bektash Wali recorded at existing ENT_SUF_BEKTASH (homonymous figure, two tradition-receptions).'),
 ('ENT_ALV_HAJI_BEKTASH','member_of','ENT_SUF_BEKTASHI','medium','Haji Bektash is the eponym and pir of the Bektashiyya order (existing ENT_SUF_BEKTASHI), the institutional wing of the Alevi-Bektashi tradition.'),
 ('ENT_ALV_HIZIR','reception_of','ENT_ISL_KHIDR','high','Alevi Hizir is the reception of the immortal Khidr (existing ENT_ISL_KHIDR); homonymous figure across traditions.'),
 ('ENT_ALV_TWELVE_IMAMS','reception_of','ENT_ISL_INFALLIBLES','high','The Alevi On Iki Imam are the reception of the Twelve Imams found within the Shi''a Fourteen Infallibles (existing ENT_ISL_INFALLIBLES).'),
 ('ENT_ALV_TWELVE_IMAMS','reception_of','ENT_ISL_AHL_BAYT','medium','Alevi veneration of the Imams continues devotion to the Ahl al-Bayt (existing ENT_ISL_AHL_BAYT).'),
 ('ENT_ALV_TWELVE_IMAMS','reception_of','ENT_ISL_MAHDI','medium','The twelfth of the venerated Imams is the hidden Mahdi (existing ENT_ISL_MAHDI), awaited in Alevi eschatology.'),
 ('ENT_ALV_MUHARREM','reception_of','ENT_ISL_HUSAYN','high','The Muharrem/matem mourning commemorates the martyrdom of Husayn ibn Ali (existing ENT_ISL_HUSAYN) at Karbala.'),
 ('ENT_ALV_OCAK','reception_of','ENT_ISL_AHL_BAYT','medium','Ocak lineages claim genealogical descent from the Ahl al-Bayt (existing ENT_ISL_AHL_BAYT), grounding dede authority.'),
 ('ENT_ALV_PIR_SULTAN','aligned_with','ENT_SUF_YUNUS_EMRE','medium','Pir Sultan Abdal stands in the Anatolian Turkish saint-poet (asik) tradition exemplified by Yunus Emre (existing ENT_SUF_YUNUS_EMRE); functional/literary alignment, not identity.'),
 ('ENT_ALV_TRINITY','aligned_with','ENT_SUF_HALLAJ','low','The Alevi divinization-of-Ali motif draws on the antinomian Sufi current of divine immanence exemplified by al-Hallaj''s ''Ana al-Haqq'' (existing ENT_SUF_HALLAJ); doctrinal alignment of theme.'),
 ('ENT_ALV_BUYRUK','reception_of','ENT_ISL_SADIQ','low','The Buyruk corpus is traditionally ascribed in part to Ja''far al-Sadiq (existing ENT_ISL_SADIQ); attested ascription, not historical authorship.');
INSERT INTO entity_relationships(subject_entity_id,relationship_type,object_entity_id,confidence,rationale,source_id,review_status)
